[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ClipCast — One video is worth a thousand words</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --primary: oklch(55% 0.22 245);
      --primary-dark: oklch(48% 0.22 245);
      --accent: oklch(65% 0.22 30);
      --text: oklch(20% 0.02 265);
      --text-light: oklch(45% 0.02 265);
      --bg: oklch(99% 0.01 265);
      --bg-alt: oklch(97% 0.01 265);
      --surface: oklch(100% 0 0);
      --border: oklch(92% 0.01 265);
      --success: oklch(65% 0.18 145);
      --radius: 12px;
      --radius-sm: 8px;
      --shadow: 0 4px 24px oklch(0% 0 0 / 0.08);
      --shadow-lg: 0 12px 48px oklch(0% 0 0 / 0.12);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Navigation */
    nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      background: oklch(100% 0 0 / 0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      z-index: 1000;
      padding: 16px 0;
    }

    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 32px;
    }

    .nav-logo {
      font-weight: 800;
      font-size: 24px;
      color: var(--primary);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .nav-logo svg { width: 32px; height: 32px; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-links a {
      font-weight: 500;
      color: var(--text);
      transition: color 0.2s;
    }

    .nav-links a:hover { color: var(--primary); }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px 24px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 15px;
      border: none;
      cursor: pointer;
      transition: all 0.2s;
    }

    .btn-primary {
      background: var(--primary);
      color: white;
    }

    .btn-primary:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow);
    }

    .btn-secondary {
      background: transparent;
      color: var(--text);
      border: 1px solid var(--border);
    }

    .btn-secondary:hover {
      background: var(--bg-alt);
      border-color: var(--text-light);
    }

    .btn-accent {
      background: var(--accent);
      color: white;
    }

    .btn-accent:hover {
      filter: brightness(1.1);
      transform: translateY(-1px);
    }

    .btn-sm { padding: 8px 16px; font-size: 14px; }
    .btn-lg { padding: 16px 32px; font-size: 17px; }

    /* Cookie Banner */
    .cookie-banner {
      position: fixed;
      bottom: 24px;
      left: 50%;
      transform: translateX(-50%);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 24px;
      box-shadow: var(--shadow-lg);
      z-index: 999;
      max-width: 500px;
      width: calc(100% - 48px);
      display: none;
    }

    .cookie-banner.show { display: block; }

    .cookie-banner h4 { font-size: 16px; margin-bottom: 8px; }
    .cookie-banner p { font-size: 14px; color: var(--text-light); margin-bottom: 16px; }

    .cookie-actions {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    .cookie-actions button {
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 14px;
      border: none;
      cursor: pointer;
      transition: all 0.2s;
    }

    .cookie-accept {
      background: var(--primary);
      color: white;
    }

    .cookie-reject {
      background: var(--bg-alt);
      color: var(--text);
    }

    .cookie-manage {
      background: transparent;
      color: var(--primary);
      text-decoration: underline;
    }

    /* Cookie Modal */
    .cookie-modal {
      position: fixed;
      inset: 0;
      background: oklch(0% 0 0 / 0.5);
      z-index: 2000;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .cookie-modal.show { display: flex; }

    .cookie-modal-inner {
      background: var(--surface);
      border-radius: var(--radius-lg);
      padding: 32px;
      max-width: 480px;
      width: 100%;
      max-height: 80vh;
      overflow-y: auto;
    }

    .cookie-modal h3 { font-size: 20px; margin-bottom: 8px; }
    .cookie-modal > p { font-size: 14px; color: var(--text-light); margin-bottom: 24px; }

    .cookie-category {
      margin-bottom: 20px;
      padding-bottom: 20px;
      border-bottom: 1px solid var(--border);
    }

    .cookie-category:last-of-type { border-bottom: none; margin-bottom: 24px; }

    .cookie-category h5 { font-size: 15px; margin-bottom: 4px; display: flex; align-items: center; justify-content: space-between; }
    .cookie-category p { font-size: 13px; color: var(--text-light); }

    .toggle-switch {
      position: relative;
      width: 48px;
      height: 26px;
      background: var(--border);
      border-radius: 100px;
      cursor: pointer;
      transition: background 0.2s;
    }

    .toggle-switch::after {
      content: '';
      position: absolute;
      top: 3px;
      left: 3px;
      width: 20px;
      height: 20px;
      background: white;
      border-radius: 50%;
      transition: transform 0.2s;
    }

    .toggle-switch.active { background: var(--primary); }
    .toggle-switch.active::after { transform: translateX(22px); }

    /* Hero */
    .hero {
      padding: 160px 0 80px;
      text-align: center;
      background: linear-gradient(180deg, oklch(97% 0.01 265) 0%, var(--bg) 100%);
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: oklch(92% 0.12 265);
      padding: 6px 14px;
      border-radius: 100px;
      font-size: 13px;
      font-weight: 600;
      color: var(--primary);
      margin-bottom: 24px;
    }

    .hero h1 {
      font-size: clamp(40px, 7vw, 72px);
      font-weight: 800;
      line-height: 1.1;
      margin-bottom: 24px;
      letter-spacing: -0.03em;
    }

    .hero h1 span {
      background: linear-gradient(135deg, var(--primary) 0%, oklch(60% 0.20 280) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero p {
      font-size: 20px;
      color: var(--text-light);
      max-width: 640px;
      margin: 0 auto 40px;
    }

    .hero-actions {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .hero-visual {
      margin-top: 64px;
      background: var(--surface);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      overflow: hidden;
      border: 1px solid var(--border);
    }

    .hero-visual img {
      width: 100%;
      height: auto;
    }

    /* Logo Bar */
    .logo-bar {
      padding: 64px 0;
      background: var(--bg-alt);
    }

    .logo-bar p {
      text-align: center;
      font-size: 14px;
      color: var(--text-light);
      margin-bottom: 32px;
    }

    .logo-grid {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 48px;
      flex-wrap: wrap;
    }

    .logo-grid span {
      font-size: 18px;
      font-weight: 700;
      color: var(--text-light);
      opacity: 0.6;
    }

    /* Sections */
    section { padding: 80px 0; }
    section:nth-child(even) { background: var(--bg-alt); }

    .section-header {
      text-align: center;
      max-width: 720px;
      margin: 0 auto 56px;
    }

    .section-label {
      display: inline-block;
      font-size: 13px;
      font-weight: 600;
      color: var(--primary);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 12px;
    }

    .section-header h2 {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      line-height: 1.2;
      margin-bottom: 16px;
    }

    .section-header p {
      font-size: 18px;
      color: var(--text-light);
    }

    /* Feature Highlight */
    .feature-highlight {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .feature-highlight.reversed { direction: rtl; }
    .feature-highlight.reversed > * { direction: ltr; }

    .feature-tag {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: oklch(92% 0.18 280);
      color: oklch(45% 0.18 280);
      padding: 4px 12px;
      border-radius: 100px;
      font-size: 12px;
      font-weight: 600;
      margin-bottom: 16px;
    }

    .feature-highlight h3 {
      font-size: 32px;
      font-weight: 800;
      margin-bottom: 16px;
      line-height: 1.2;
    }

    .feature-highlight p {
      font-size: 16px;
      color: var(--text-light);
      margin-bottom: 24px;
    }

    .feature-visual {
      background: linear-gradient(135deg, oklch(95% 0.05 265) 0%, oklch(92% 0.08 280) 100%);
      border-radius: var(--radius-lg);
      padding: 48px;
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 300px;
    }

    .feature-visual-inner {
      background: var(--surface);
      border-radius: var(--radius);
      padding: 24px;
      box-shadow: var(--shadow);
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .feature-icon {
      width: 48px;
      height: 48px;
      background: var(--primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
    }

    /* Screen Recorder Section */
    .recorder-features {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      margin-top: 48px;
    }

    .recorder-feature {
      text-align: center;
      padding: 32px;
      background: var(--surface);
      border-radius: var(--radius);
      border: 1px solid var(--border);
    }

    .recorder-feature-icon {
      width: 56px;
      height: 56px;
      background: oklch(92% 0.12 265);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
      font-size: 24px;
    }

    .recorder-feature h4 { font-size: 18px; margin-bottom: 8px; }
    .recorder-feature p { font-size: 14px; color: var(--text-light); }

    /* Video Editor */
    .editor-features {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .editor-feature {
      padding: 24px;
      background: var(--surface);
      border-radius: var(--radius);
      border: 1px solid var(--border);
    }

    .editor-feature h4 {
      font-size: 16px;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .editor-feature p { font-size: 14px; color: var(--text-light); }

    /* Integrations */
    .integrations-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 16px;
    }

    .integration-item {
      aspect-ratio: 1;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
      transition: all 0.2s;
    }

    .integration-item:hover {
      border-color: var(--primary);
      transform: translateY(-2px);
      box-shadow: var(--shadow);
    }

    /* Engagement */
    .engagement-cards {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .engagement-card {
      padding: 32px;
      background: var(--surface);
      border-radius: var(--radius);
      border: 1px solid var(--border);
    }

    .engagement-card h4 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
    .engagement-card p { font-size: 14px; color: var(--text-light); }

    /* Security */
    .security-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .security-item {
      text-align: center;
      padding: 24px;
    }

    .security-icon {
      width: 64px;
      height: 64px;
      background: oklch(92% 0.12 145);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
      font-size: 28px;
    }

    .security-item h4 { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
    .security-item p { font-size: 13px; color: var(--text-light); }

    /* Use Cases */
    .use-cases-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .use-case-card {
      padding: 32px 24px;
      background: var(--surface);
      border-radius: var(--radius);
      border: 1px solid var(--border);
      text-align: center;
      transition: all 0.2s;
    }

    .use-case-card:hover {
      border-color: var(--primary);
      transform: translateY(-2px);
    }

    .use-case-icon {
      width: 56px;
      height: 56px;
      background: oklch(92% 0.12 265);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
      font-size: 24px;
    }

    .use-case-card h4 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
    .use-case-card p { font-size: 14px; color: var(--text-light); }

    /* Features Grid */
    .features-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }

    .feature-item {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 16px;
      background: var(--surface);
      border-radius: var(--radius-sm);
      border: 1px solid var(--border);
    }

    .feature-check {
      width: 24px;
      height: 24px;
      background: var(--primary);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 12px;
      flex-shrink: 0;
    }

    .feature-item span { font-size: 14px; font-weight: 500; }

    /* Blog */
    .blog-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 32px;
    }

    .blog-card {
      background: var(--surface);
      border-radius: var(--radius);
      border: 1px solid var(--border);
      overflow: hidden;
      transition: all 0.2s;
    }

    .blog-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow);
    }

    .blog-image {
      height: 180px;
      background: linear-gradient(135deg, oklch(92% 0.08 265) 0%, oklch(88% 0.12 280) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
    }

    .blog-content { padding: 24px; }
    .blog-content h4 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
    .blog-content p { font-size: 14px; color: var(--text-light); margin-bottom: 16px; }
    .blog-content a { color: var(--primary); font-weight: 600; font-size: 14px; }

    /* Enterprise CTA */
    .enterprise-cta-block {
      background: linear-gradient(135deg, var(--primary) 0%, oklch(50% 0.22 280) 100%);
      border-radius: var(--radius-lg);
      padding: 64px;
      text-align: center;
      color: white;
    }

    .enterprise-cta-block h2 { font-size: 32px; margin-bottom: 16px; }
    .enterprise-cta-block p { font-size: 18px; opacity: 0.9; margin-bottom: 32px; }
    .enterprise-cta-block .btn {
      background: white;
      color: var(--primary);
    }

    .enterprise-cta-block .btn:hover {
      transform: translateY(-1px);
      box-shadow: var(--shadow);
    }

    /* Testimonials */
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .testimonial-card {
      padding: 32px;
      background: var(--surface);
      border-radius: var(--radius);
      border: 1px solid var(--border);
    }

    .testimonial-quote {
      font-size: 16px;
      line-height: 1.7;
      margin-bottom: 24px;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 48px;
      height: 48px;
      background: linear-gradient(135deg, var(--primary) 0%, oklch(60% 0.20 280) 100%);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-weight: 700;
      font-size: 18px;
    }

    .testimonial-info h5 { font-size: 15px; font-weight: 600; }
    .testimonial-info p { font-size: 13px; color: var(--text-light); }

    /* CTA Banner */
    .cta-banner {
      background: var(--text);
      color: white;
      text-align: center;
      padding: 64px 0;
    }

    .cta-banner h2 { font-size: 32px; margin-bottom: 16px; }
    .cta-banner p { font-size: 16px; opacity: 0.8; margin-bottom: 32px; }
    .cta-banner .btn-accent { background: var(--accent); }

    /* Footer */
    footer {
      background: var(--text);
      color: white;
      padding: 80px 0 40px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(5, 1fr);
      gap: 48px;
      margin-bottom: 64px;
    }

    .footer-brand p {
      font-size: 14px;
      opacity: 0.7;
      margin-top: 16px;
      max-width: 280px;
    }

    .footer-col h5 {
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 16px;
      opacity: 0.5;
    }

    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 10px; }
    .footer-col a {
      font-size: 14px;
      opacity: 0.7;
      transition: opacity 0.2s;
    }

    .footer-col a:hover { opacity: 1; }

    .footer-bottom {
      border-top: 1px solid oklch(100% 0 0 / 0.1);
      padding-top: 40px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .footer-bottom p { font-size: 13px; opacity: 0.5; }

    .footer-social { display: flex; gap: 16px; }
    .footer-social a { opacity: 0.5; transition: opacity 0.2s; font-size: 20px; }
    .footer-social a:hover { opacity: 1; }

    /* Responsive */
    @media (max-width: 1024px) {
      .feature-highlight { grid-template-columns: 1fr; gap: 40px; }
      .feature-highlight.reversed { direction: ltr; }
      .recorder-features { grid-template-columns: 1fr; }
      .editor-features { grid-template-columns: 1fr; }
      .integrations-grid { grid-template-columns: repeat(4, 1fr); }
      .engagement-cards { grid-template-columns: 1fr; }
      .security-grid { grid-template-columns: repeat(2, 1fr); }
      .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
      .features-grid { grid-template-columns: repeat(2, 1fr); }
      .testimonials-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .hero { padding: 120px 0 60px; }
      section { padding: 60px 0; }
      .enterprise-cta-block { padding: 40px 24px; }
      .footer-grid { grid-template-columns: 1fr; gap: 32px; }
      .footer-bottom { flex-direction: column; gap: 16px; }
    }
  </style>
</head>
<body>
  <!-- Navigation -->
  <nav>
    <div class="container nav-inner">
      <a href="index.html" class="nav-logo">
        <svg viewBox="0 0 32 32" fill="none">
          <rect width="32" height="32" rx="8" fill="currentColor"/>
          <path d="M12 10l8 6-8 6V10z" fill="white"/>
        </svg>
        ClipCast
      </a>
      <div class="nav-links">
        <a href="enterprise.html">Enterprise</a>
        <a href="pricing.html">Pricing</a>
        <a href="#">Resources</a>
        <a href="#">Blog</a>
      </div>
      <div class="nav-actions">
        <a href="login.html" class="btn btn-secondary btn-sm">Sign In</a>
        <a href="signup.html" class="btn btn-primary btn-sm">Get Started for free</a>
      </div>
    </div>
  </nav>

  <!-- Cookie Banner -->
  <div id="cookieBanner" class="cookie-banner">
    <h4>We value your privacy</h4>
    <p>We use cookies to enhance your browsing experience, serve personalized content, and analyze our traffic. By clicking "Accept all", you consent to our use of cookies.</p>
    <div class="cookie-actions">
      <button class="cookie-accept" onclick="acceptCookies()">Accept all</button>
      <button class="cookie-reject" onclick="rejectCookies()">Reject all</button>
      <button class="cookie-manage" onclick="showCookieModal()">Manage preferences</button>
    </div>
  </div>

  <!-- Cookie Modal -->
  <div id="cookieModal" class="cookie-modal">
