      font-family: inherit;
      background: var(--bg);
      transition: all 0.2s;
    }

    .form-group input:focus {
      outline: none;
      border-color: var(--primary);
      box-shadow: 0 0 0 3px oklch(55% 0.22 245 / 0.1);
    }

    .form-group input::placeholder {
      color: var(--text-light);
    }

