      padding: 14px 24px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 15px;
      border: none;
      cursor: pointer;
      transition: all 0.2s;
      background: var(--primary);
      color: white;
      width: 100%;
    }

    .btn-primary:hover {
      background: var(--primary-dark);
    }

    .signup-footer {
      text-align: center;
      margin-top: 24px;
      font-size: 14px;
      color: var(--text-light);
    }

    .signup-footer a {
      color: var(--primary);
      font-weight: 600;
    }

    .signup-footer a:hover {
      text-decoration: underline;
    }

    .legal-text {
      text-align: center;
      margin-top: 24px;
      font-size: 12px;
      color: var(--text-light);
      line-height: 1.6;
    }

    /* Testimonial Sidebar */
    .testimonial-sidebar {
      background: linear-gradient(135deg, var(--primary) 0%, oklch(50% 0.22 280) 100%);
      border-radius: var(--radius-lg);
      padding: 48px;
      color: white;
    }

    .testimonial-sidebar h3 {
      font-size: 20px;
      margin-bottom: 32px;
      line-height: 1.4;
    }

    .testimonial-item {
      margin-bottom: 32px;
    }

    .testimonial-item:last-child {
      margin-bottom: 0;
    }

    .testimonial-quote {
      font-size: 15px;
      line-height: 1.7;
      margin-bottom: 16px;
      opacity: 0.95;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 44px;
      height: 44px;
      background: oklch(100% 0 0 / 0.2);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 16px;
    }

    .testimonial-info h5 {
      font-size: 14px;
      font-weight: 600;
    }

    .testimonial-info p {
      font-size: 12px;
      opacity: 0.8;
    }

    .testimonial-stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin-top: 40px;
      padding-top: 32px;
      border-top: 1px solid oklch(100% 0 0 / 0.2);
    }

    .stat-item {
      text-align: center;
    }

    .stat-item .number {
      font-size: 28px;
      font-weight: 800;
      display: block;
