    .stat-item .label {
      font-size: 12px;
      opacity: 0.8;
    }

    footer {
      padding: 24px;
      text-align: center;
      border-top: 1px solid var(--border);
    }

    footer p {
      font-size: 13px;
      color: var(--text-light);
    }

    footer a {
      color: var(--text-light);
      margin: 0 8px;
    }

    footer a:hover { color: var(--text); }

